'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );


// CONSTANTS //

var SQRT2_ERFINV_HALF = 0.6744897501960818;


// MAIN //

/**
* Returns the median for a half-normal distribution with scale parameter `sigma`.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} median
*
* @example
* var y = median( 1.0 );
* // returns ~0.6744897501960818
*
* @example
* var y = median( 4.0 );
* // returns ~2.6979590007843268
*
* @example
* var y = median( NaN );
* // returns NaN
*
* @example
* var y = median( 0.0 );
* // returns NaN
*/
function median( sigma ) {
	if (
		isnan( sigma ) ||
		sigma <= 0.0
	) {
		return NaN;
	}
	return sigma * SQRT2_ERFINV_HALF;
}


// EXPORTS //

module.exports = median;
